// Reprobation
// status: ready
// Enchant creature
// Enchanted creature loses all abilities and is a Coward creature with base power and toughness 0/1. (It keeps all supertypes but loses all other types and creature types.)
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_enchant(q: &dyn Query, asker: &Asker, t: Target) -> bool { matches!(t, Target::Object(id) if cantrip_mechanics::targets::permanent(q, id) && (q.chars(id).is(CardType::Creature))) }
#[allow(unused_variables)] fn ability_1_apply_1(q: &dyn LayerQuery, source: ObjectId, chars: &mut Chars) { let asker = &Asker::new(source, q.controller(source)); chars.subtypes = chars.subtypes.minus(SubtypeSet::CREATURE_TYPES); if (chars.is(CardType::Creature) || chars.is(CardType::Kindred)) { chars.subtypes = chars.subtypes.with(q.words(asker.source).subtype(Subtype::Coward)); } }
#[allow(unused_variables)] fn ability_1_apply_2(q: &dyn LayerQuery, source: ObjectId, chars: &mut Chars) { let asker = &Asker::new(source, q.controller(source)); let kept = TypeSet::of(&[CardType::Creature]); chars.types = kept; chars.subtypes = chars.subtypes.iter().filter(|s| s.card_types().0 & kept.0 != 0).fold(SubtypeSet::NONE, SubtypeSet::with); }
#[allow(unused_variables)] fn ability_1_apply_3(q: &dyn LayerQuery, source: ObjectId, chars: &mut Chars) { let asker = &Asker::new(source, q.controller(source)); let (p, t) = ((0i64) as i16, (1i64) as i16); chars.power = Some(p); chars.toughness = Some(t); }

